@page "/dashboard"
@inject sv_2d8a4ef861234b9ab0b8bbbe649fe442.Services.WarehouseState WarehouseState
@inject sv_2d8a4ef861234b9ab0b8bbbe649fe442.Services.InventoryAlertService AlertService
@implements IAsyncDisposable
@rendermode InteractiveServer

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mt-3">
    <div class="card-header">
        <strong>@WarehouseState.SelectedWarehouseName</strong> — Inventory Status
    </div>
    <div class="card-body">
        <p>
            Low-stock items:
            <span class="badge bg-warning text-dark fs-5">@AlertService.CurrentLowStockCount</span>
        </p>
        <p class="text-muted mb-0">
            Polling every 10 seconds. Last refresh: @_lastRefresh?.ToString("HH:mm:ss")
        </p>
    </div>
</div>

@code {
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private DateTime? _lastRefresh;
    private Action? _warehouseHandler;
    private Action? _alertHandler;

    protected override async Task OnInitializedAsync()
    {
        // Subscribe to warehouse changes so we refresh immediately on switch
        _warehouseHandler = () => InvokeAsync(OnWarehouseChanged);
        WarehouseState.OnChange += _warehouseHandler;

        // Subscribe to alert changes so the dashboard re-renders when data arrives
        _alertHandler = () => InvokeAsync(StateHasChanged);
        AlertService.OnAlertCountChanged += _alertHandler;

        // Initial fetch
        await AlertService.RefreshAsync(WarehouseState.SelectedWarehouseId);
        _lastRefresh = DateTime.Now;

        // Start polling
        StartPolling();
    }

    private async void OnWarehouseChanged()
    {
        // When warehouse changes, refresh immediately and restart polling
        StopPolling();
        await AlertService.RefreshAsync(WarehouseState.SelectedWarehouseId);
        _lastRefresh = DateTime.Now;
        StateHasChanged();
        StartPolling();
    }

    private void StartPolling()
    {
        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        _ = PollLoopAsync(_cts.Token);
    }

    private void StopPolling()
    {
        _cts?.Cancel();
        _timer?.Dispose();
        _timer = null;
    }

    private async Task PollLoopAsync(CancellationToken cancellationToken)
    {
        try
        {
            while (await _timer!.WaitForNextTickAsync(cancellationToken))
            {
                await InvokeAsync(async () =>
                {
                    await AlertService.RefreshAsync(WarehouseState.SelectedWarehouseId);
                    _lastRefresh = DateTime.Now;
                    StateHasChanged();
                });
            }
        }
        catch (OperationCanceledException)
        {
            // Expected on dispose or warehouse switch
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (_warehouseHandler is not null)
            WarehouseState.OnChange -= _warehouseHandler;
        if (_alertHandler is not null)
            AlertService.OnAlertCountChanged -= _alertHandler;

        StopPolling();
        _cts?.Dispose();
    }
}

